fn run_health_probe(
    identity: HealthProbeIdentity,
    ready: Arc<AtomicBool>,
    shutdown: Arc<AtomicBool>,
) {
    let mut request_id = 1_u64;
    while !shutdown.load(Ordering::Acquire) {
        ready.store(
            probe_health_once(&identity, request_id).unwrap_or(false),
            Ordering::Release,
        );
        request_id = request_id.wrapping_add(1).max(1);
        std::thread::sleep(HEALTH_PROBE_INTERVAL);
    }
    ready.store(false, Ordering::Release);
}

fn probe_health_once(
    identity: &HealthProbeIdentity,
    request_id: u64,
) -> Result<bool, ProcessDriverError> {
    Ok(query_health_once(identity, request_id)?.ready)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct HealthProbeObservation {
    exact_identity: bool,
    ready: bool,
}

fn prove_adoption_identity(identity: &HealthProbeIdentity) -> bool {
    for request_id in 1..=ADOPTION_PROBE_ATTEMPTS {
        if query_health_once(identity, request_id)
            .is_ok_and(|observation| observation.exact_identity)
        {
            return true;
        }
        if request_id != ADOPTION_PROBE_ATTEMPTS {
            std::thread::sleep(HEALTH_PROBE_INTERVAL);
        }
    }
    false
}

fn query_health_once(
    identity: &HealthProbeIdentity,
    request_id: u64,
) -> Result<HealthProbeObservation, ProcessDriverError> {
    match identity {
        HealthProbeIdentity::Agentd(identity) => query_agent_health_once(identity, request_id),
        HealthProbeIdentity::Matrixd(identity) => query_matrix_health_once(identity, request_id),
    }
}

fn query_agent_health_once(
    identity: &AgentHealthProbeIdentity,
    request_id: u64,
) -> Result<HealthProbeObservation, ProcessDriverError> {
    let request = AgentdRequest::health(request_id, identity.spawn_generation);
    let mut bytes = serde_json::to_vec(&request)?;
    bytes.push(b'\n');
    if bytes.len() as u64 > MAX_CONTROL_FRAME_BYTES {
        return Ok(HealthProbeObservation {
            exact_identity: false,
            ready: false,
        });
    }

    let mut stream = std::os::unix::net::UnixStream::connect(&identity.control_socket)?;
    stream.set_read_timeout(Some(HEALTH_PROBE_IO_TIMEOUT))?;
    stream.set_write_timeout(Some(HEALTH_PROBE_IO_TIMEOUT))?;
    stream.write_all(&bytes)?;
    stream.shutdown(Shutdown::Write)?;

    let mut reader = BufReader::new(stream).take(MAX_CONTROL_FRAME_BYTES + 1);
    let mut response_bytes = Vec::new();
    let count = reader.read_until(b'\n', &mut response_bytes)?;
    if count == 0 || count as u64 > MAX_CONTROL_FRAME_BYTES || !response_bytes.ends_with(b"\n") {
        return Ok(HealthProbeObservation {
            exact_identity: false,
            ready: false,
        });
    }
    let response: AgentdResponse = serde_json::from_slice(&response_bytes)?;
    let exact_envelope = response.schema_version == AGENTD_CONTROL_SCHEMA_VERSION
        && response.request_id == request_id
        && response.agent_id == identity.agent_id
        && response.spawn_generation == identity.spawn_generation;
    let AgentdPayload::Health(health) = response.payload else {
        return Ok(HealthProbeObservation {
            exact_identity: false,
            ready: false,
        });
    };
    let generation_matches = match health.lifecycle {
        AgentLifecycle::Starting => response.current_generation == identity.spawn_generation,
        AgentLifecycle::Running => identity
            .spawn_generation
            .checked_add(1)
            .is_some_and(|generation| response.current_generation == generation),
        AgentLifecycle::Draining => identity
            .spawn_generation
            .checked_add(2)
            .is_some_and(|generation| response.current_generation == generation),
        AgentLifecycle::Stopped | AgentLifecycle::Failed => false,
    };
    let readiness_matches = match health.lifecycle {
        AgentLifecycle::Starting => health.promotion_ready && !health.ready,
        AgentLifecycle::Running => health.promotion_ready && health.ready,
        AgentLifecycle::Draining | AgentLifecycle::Stopped | AgentLifecycle::Failed => false,
    };
    let exact_identity = exact_envelope
        && generation_matches
        && !health.fenced
        && health.process_id == identity.process_id
        && health.workspace == identity.workspace
        && health.home_root == identity.home_root
        && health.run_root == identity.run_root;
    Ok(HealthProbeObservation {
        exact_identity,
        ready: exact_identity && readiness_matches,
    })
}

fn read_agent_drain_frame(
    identity: &AgentHealthProbeIdentity,
    request: &[u8],
) -> std::io::Result<Vec<u8>> {
    let mut stream = std::os::unix::net::UnixStream::connect(&identity.control_socket)?;
    stream.set_read_timeout(Some(HEALTH_PROBE_IO_TIMEOUT))?;
    stream.set_write_timeout(Some(HEALTH_PROBE_IO_TIMEOUT))?;
    stream.write_all(request)?;
    stream.shutdown(Shutdown::Write)?;
    let mut reader = BufReader::new(stream).take(MAX_CONTROL_FRAME_BYTES + 1);
    let mut response = Vec::new();
    reader.read_until(b'\n', &mut response)?;
    Ok(response)
}

fn query_agent_drain_once(
    identity: &AgentHealthProbeIdentity,
    request_id: u64,
) -> Result<bool, ProcessDriverError> {
    let request = AgentdRequest::drain(request_id, identity.spawn_generation);
    let mut bytes = serde_json::to_vec(&request)?;
    bytes.push(b'\n');
    if bytes.len() as u64 > MAX_CONTROL_FRAME_BYTES {
        return Err(ProcessDriverError::new(
            "Agentd drain request exceeded the bounded control frame",
        ));
    }
    interpret_agent_drain_response(
        identity,
        request_id,
        read_agent_drain_frame(identity, &bytes),
    )
}

fn interpret_agent_drain_response(
    identity: &AgentHealthProbeIdentity,
    request_id: u64,
    response: std::io::Result<Vec<u8>>,
) -> Result<bool, ProcessDriverError> {
    let response_bytes = match response {
        Ok(response) => response,
        Err(error)
            if matches!(
                error.kind(),
                std::io::ErrorKind::NotFound
                    | std::io::ErrorKind::ConnectionRefused
                    | std::io::ErrorKind::ConnectionReset
                    | std::io::ErrorKind::ConnectionAborted
                    | std::io::ErrorKind::NotConnected
                    | std::io::ErrorKind::BrokenPipe
                    | std::io::ErrorKind::TimedOut
                    | std::io::ErrorKind::WouldBlock
                    | std::io::ErrorKind::UnexpectedEof
                    | std::io::ErrorKind::Interrupted
            ) =>
        {
            // Shutdown can remove the control socket or disconnect a peer before
            // waitpid sees exit. On macOS, half-closing that peer can return
            // NotConnected. None of these transport errors proves a drain ACK.
            // No response is NOT a drain acknowledgement. Preserve the existing
            // deadline/escalation path instead of aborting lifecycle observation.
            return Ok(false);
        }
        Err(error) => return Err(error.into()),
    };
    if response_bytes.is_empty() {
        return Ok(false);
    }
    if response_bytes.len() as u64 > MAX_CONTROL_FRAME_BYTES || !response_bytes.ends_with(b"\n") {
        return Err(ProcessDriverError::new(
            "Agentd drain response was not a bounded complete frame",
        ));
    }
    let response: AgentdResponse = serde_json::from_slice(&response_bytes)?;
    let exact_envelope = response.schema_version == AGENTD_CONTROL_SCHEMA_VERSION
        && response.request_id == request_id
        && response.agent_id == identity.agent_id
        && response.spawn_generation == identity.spawn_generation
        && identity
            .spawn_generation
            .checked_add(2)
            .is_some_and(|generation| response.current_generation == generation);
    let AgentdPayload::Drain(snapshot) = response.payload else {
        return Err(ProcessDriverError::new(
            "Agentd drain request did not return a drain acknowledgement",
        ));
    };
    if !exact_envelope
        || snapshot.lifecycle != AgentLifecycle::Draining
        || snapshot.fenced
        || !snapshot.admission_closed
    {
        return Err(ProcessDriverError::new(
            "Agentd drain acknowledgement did not bind the current draining generation",
        ));
    }
    Ok(snapshot.drained && snapshot.running_turns == 0)
}

fn query_matrix_health_once(
    identity: &MatrixHealthProbeIdentity,
    request_id: u64,
) -> Result<HealthProbeObservation, ProcessDriverError> {
    let request = MatrixdRequest {
        schema_version: MATRIXD_CONTROL_SCHEMA_VERSION,
        request_id,
        agent_id: identity.agent_id.clone(),
        fence: None,
        method: MatrixdMethod::Health,
    };
    let mut bytes = serde_json::to_vec(&request)?;
    bytes.push(b'\n');
    if bytes.len() as u64 > MAX_MATRIXD_CONTROL_FRAME_BYTES {
        return Ok(HealthProbeObservation {
            exact_identity: false,
            ready: false,
        });
    }

    let mut stream = std::os::unix::net::UnixStream::connect(&identity.control_socket)?;
    stream.set_read_timeout(Some(HEALTH_PROBE_IO_TIMEOUT))?;
    stream.set_write_timeout(Some(HEALTH_PROBE_IO_TIMEOUT))?;
    stream.write_all(&bytes)?;
    stream.shutdown(Shutdown::Write)?;

    let mut reader = BufReader::new(stream).take(MAX_MATRIXD_CONTROL_FRAME_BYTES + 1);
    let mut response_bytes = Vec::new();
    let count = reader.read_until(b'\n', &mut response_bytes)?;
    if count == 0
        || count as u64 > MAX_MATRIXD_CONTROL_FRAME_BYTES
        || !response_bytes.ends_with(b"\n")
    {
        return Ok(HealthProbeObservation {
            exact_identity: false,
            ready: false,
        });
    }
    let response: MatrixdResponse = serde_json::from_slice(&response_bytes)?;
    if response.validate().is_err() {
        return Ok(HealthProbeObservation {
            exact_identity: false,
            ready: false,
        });
    }
    let exact_envelope = response.schema_version == MATRIXD_CONTROL_SCHEMA_VERSION
        && response.request_id == request_id
        && response.agent_id == identity.agent_id
        && response.release_id == identity.release_id
        && response.binding_revision == identity.binding_revision
        && response.binding_digest == identity.binding_digest
        && response.attached_agent_generation == identity.agent_generation
        && response.process_incarnation == identity.process_incarnation
        && response.plane_epoch == identity.plane_epoch;
    let MatrixdPayload::Health(MatrixdHealth {
        lifecycle,
        process_id,
        agentd_connected,
        matrix_sync_connected,
        fenced,
    }) = response.payload
    else {
        return Ok(HealthProbeObservation {
            exact_identity: false,
            ready: false,
        });
    };
    let exact_identity = exact_envelope && process_id == identity.process_id && !fenced;
    let ready = exact_identity
        && lifecycle == MatrixdLifecycle::Ready
        && agentd_connected
        && matrix_sync_connected;
    Ok(HealthProbeObservation {
        exact_identity,
        ready,
    })
}

fn spawn_log_reader(
    mut reader: impl Read + Send + 'static,
    stream: ProcessStream,
    sender: SyncSender<ProcessLog>,
) {
    std::thread::spawn(move || {
        let mut buffer = [0_u8; LOG_CHUNK_BYTES];
        loop {
            let count = match reader.read(&mut buffer) {
                Ok(0) | Err(_) => break,
                Ok(count) => count,
            };
            let _ = sender.try_send(ProcessLog {
                stream,
                bytes: buffer[..count].to_vec(),
            });
        }
    });
}

fn send_signal(pid: u32, signal: i32) -> Result<(), ProcessDriverError> {
    let pid = i32::try_from(pid)
        .map_err(|_| ProcessDriverError::new("child PID does not fit Unix pid_t"))?;
    // SAFETY: `pid` comes from std::process::Child and `signal` is a fixed libc signal constant.
    if unsafe { libc::kill(pid, signal) } == -1 {
        Err(std::io::Error::last_os_error().into())
    } else {
        Ok(())
    }
}

fn process_exists(system_id: u64) -> Result<bool, ProcessDriverError> {
    let pid = i32::try_from(system_id)
        .map_err(|_| ProcessDriverError::new("stored child PID does not fit Unix pid_t"))?;
    // SAFETY: signal 0 performs an existence/permission check without delivering a signal.
    if unsafe { libc::kill(pid, 0) } == 0 {
        return Ok(true);
    }
    let error = std::io::Error::last_os_error();
    if error.raw_os_error() == Some(libc::ESRCH) {
        Ok(false)
    } else if error.raw_os_error() == Some(libc::EPERM) {
        Ok(true)
    } else {
        Err(error.into())
    }
}

/// Poll an adopted process without confusing a terminated child zombie for a
/// live process. After supervisor recovery the process normally is not our
/// child, in which case `waitpid` returns `ECHILD` and the exact UDS adoption
/// proof remains the sole source of signal authority; here we only observe its
/// continued existence with signal 0.
fn poll_adopted_process(process_id: u32) -> Result<Option<ProcessExit>, ProcessDriverError> {
    let pid = i32::try_from(process_id)
        .map_err(|_| ProcessDriverError::new("adopted child PID does not fit Unix pid_t"))?;
    let mut status = 0_i32;
    // SAFETY: `pid` is the exact process identity proven during adoption,
    // `status` points to writable storage, and WNOHANG never blocks.
    let waited = unsafe { libc::waitpid(pid, &mut status, libc::WNOHANG) };
    if waited > 0 {
        let exited = libc::WIFEXITED(status);
        return Ok(Some(ProcessExit {
            success: exited && libc::WEXITSTATUS(status) == 0,
            code: exited.then(|| libc::WEXITSTATUS(status)),
        }));
    }
    if waited == 0 {
        return Ok(None);
    }

    let error = std::io::Error::last_os_error();
    if error.raw_os_error() == Some(libc::ECHILD) {
        return process_exists(u64::from(process_id)).map(|exists| {
            (!exists).then_some(ProcessExit {
                success: false,
                code: None,
            })
        });
    }
    Err(error.into())
}

#[cfg(test)]
#[path = "unix_tests.rs"]
mod tests;

#[cfg(test)]
#[path = "unix_drain_tests.rs"]
mod drain_tests;

use std::io::BufRead;
use std::io::BufReader;
use std::io::Write;
use std::net::Shutdown;
use std::os::unix::net::UnixDatagram;
use std::os::unix::net::UnixListener;
use std::os::unix::net::UnixStream;

use codex_hepta_agent_protocol::AGENTD_CONTROL_SCHEMA_VERSION;
use codex_hepta_agent_protocol::AgentdPayload;
use codex_hepta_agent_protocol::AgentdResponse;
use codex_hepta_agent_protocol::DrainSnapshot;
use codex_hepta_contracts::AgentId;
use codex_hepta_fleet::AgentLifecycle;

use super::AgentHealthProbeIdentity;
use super::interpret_agent_drain_response;
use super::query_agent_drain_once;
use crate::ProcessDriverError;

type TestResult<T = ()> = Result<T, Box<dyn std::error::Error>>;

fn identity(temp: &tempfile::TempDir) -> TestResult<AgentHealthProbeIdentity> {
    Ok(AgentHealthProbeIdentity {
        agent_id: AgentId::parse("018f4f72-5f8f-7cc1-8f55-df9fb3aa2c12")?,
        spawn_generation: 7,
        process_id: std::process::id(),
        workspace: temp.path().to_path_buf(),
        home_root: temp.path().join("home"),
        run_root: temp.path().join("run"),
        control_socket: temp.path().join("drain.sock"),
    })
}

fn exchange(
    identity: &AgentHealthProbeIdentity,
    bytes: Vec<u8>,
) -> TestResult<Result<bool, ProcessDriverError>> {
    let listener = UnixListener::bind(&identity.control_socket)?;
    let server = std::thread::spawn(move || -> std::io::Result<()> {
        let (mut stream, _) = listener.accept()?;
        let mut request = String::new();
        BufReader::new(&mut stream).read_line(&mut request)?;
        stream.write_all(&bytes)
    });
    let observed = query_agent_drain_once(identity, 17);
    let completion = server
        .join()
        .map_err(|_| std::io::Error::other("test server panic"))?;
    std::fs::remove_file(&identity.control_socket)?;
    completion?;
    Ok(observed)
}

fn acknowledgement(identity: &AgentHealthProbeIdentity) -> AgentdResponse {
    AgentdResponse {
        schema_version: AGENTD_CONTROL_SCHEMA_VERSION,
        request_id: 17,
        agent_id: identity.agent_id.clone(),
        spawn_generation: 7,
        current_generation: 9,
        payload: AgentdPayload::Drain(DrainSnapshot {
            admission_closed: true,
            running_turns: 0,
            drained: true,
            lifecycle: AgentLifecycle::Draining,
            fenced: false,
        }),
    }
}

fn frame(response: &AgentdResponse) -> TestResult<Vec<u8>> {
    let mut bytes = serde_json::to_vec(response)?;
    bytes.push(b'\n');
    Ok(bytes)
}

#[test]
fn missing_or_closed_socket_never_becomes_a_drain_acknowledgement() -> TestResult {
    let temp = tempfile::tempdir()?;
    let identity = identity(&temp)?;
    assert!(!query_agent_drain_once(&identity, 17)?);
    assert!(!exchange(&identity, Vec::new())??);
    assert!(!query_agent_drain_once(&identity, 18)?);
    Ok(())
}

#[test]
fn malformed_or_wrong_generation_drain_frames_still_reject() -> TestResult {
    let temp = tempfile::tempdir()?;
    let identity = identity(&temp)?;
    assert!(exchange(&identity, b"not-json\n".to_vec())?.is_err());
    assert!(exchange(&identity, b"{}".to_vec())?.is_err());
    let mut response = acknowledgement(&identity);
    response.current_generation = 8;
    assert!(exchange(&identity, frame(&response)?)?.is_err());
    response.current_generation = 9;
    response.request_id = 16;
    assert!(exchange(&identity, frame(&response)?)?.is_err());
    Ok(())
}

#[test]
fn only_exact_closed_admission_with_no_running_turns_is_drained() -> TestResult {
    let temp = tempfile::tempdir()?;
    let identity = identity(&temp)?;
    let response = acknowledgement(&identity);
    assert!(exchange(&identity, frame(&response)?)??);
    let mut busy = response.clone();
    if let AgentdPayload::Drain(snapshot) = &mut busy.payload {
        snapshot.running_turns = 1;
    }
    assert!(!exchange(&identity, frame(&busy)?)??);
    let mut fenced = response;
    if let AgentdPayload::Drain(snapshot) = &mut fenced.payload {
        snapshot.fenced = true;
    }
    assert!(exchange(&identity, frame(&fenced)?)?.is_err());
    Ok(())
}

#[test]
fn disconnected_peer_never_becomes_a_drain_acknowledgement() -> TestResult {
    let temp = tempfile::tempdir()?;
    let identity = identity(&temp)?;
    let (stream, peer) = UnixStream::pair()?;
    drop(peer);
    let shutdown = stream.shutdown(Shutdown::Write);
    let shutdown_error = shutdown
        .as_ref()
        .err()
        .map(|error| (error.kind(), error.raw_os_error()));
    #[cfg(target_os = "macos")]
    assert_eq!(
        shutdown_error,
        Some((std::io::ErrorKind::NotConnected, Some(libc::ENOTCONN)))
    );
    let observed = interpret_agent_drain_response(&identity, 17, shutdown.map(|()| Vec::new()));
    eprintln!("DRAIN_CLOSED_PEER shutdown_error={shutdown_error:?} observed={observed:?}");
    assert!(
        matches!(observed, Ok(false)),
        "a disconnected peer cannot acknowledge drain: {observed:?}"
    );

    #[cfg(target_os = "linux")]
    {
        // Linux permits shutdown after this peer closes. Obtain a real ENOTCONN
        // from getpeername on an unconnected socket to exercise the same error
        // classifier; this does not reproduce the macOS shutdown race.
        let socket = UnixDatagram::unbound()?;
        let error = socket
            .peer_addr()
            .expect_err("an unconnected datagram must not have a peer");
        assert_eq!(error.kind(), std::io::ErrorKind::NotConnected);
        assert_eq!(error.raw_os_error(), Some(libc::ENOTCONN));
        let observed = interpret_agent_drain_response(&identity, 18, Err(error));
        eprintln!(
            "DRAIN_NOT_CONNECTED kernel_errno={} observed={observed:?}",
            libc::ENOTCONN
        );
        assert!(
            matches!(observed, Ok(false)),
            "a disconnected transport cannot acknowledge drain: {observed:?}"
        );
    }
    Ok(())
}

#[test]
fn wrong_socket_protocol_remains_a_driver_fault() -> TestResult {
    let temp = tempfile::tempdir()?;
    let identity = identity(&temp)?;
    let _wrong_protocol = UnixDatagram::bind(&identity.control_socket)?;
    let error = UnixStream::connect(&identity.control_socket)
        .expect_err("a stream must not connect to a datagram control socket");
    assert_eq!(error.raw_os_error(), Some(libc::EPROTOTYPE));
    let fault = query_agent_drain_once(&identity, 17)
        .expect_err("a wrong socket protocol must remain a driver fault");
    assert_eq!(fault.to_string(), error.to_string());
    Ok(())
}
